/* Rootline — native offline-first emotional pattern archive. No dependencies. */
(() => {
  'use strict';
  const STORE = window.RootlineStorage;
  const SCHEMA_VERSION = 1;
  const RELATIONSHIPS = ['Mother','Partner','Friend','Sibling','Other family','Work','Myself','Other'];
  const EMOTIONS = ['Anger','Fear','Sadness','Hurt','Shame','Guilt','Jealousy','Grief','Anxiety','Disgust','Confusion','Overwhelm','Relief','Joy','Calm','Other'];
  const TAXONOMY = [
    ['P01','Abandonment alarm','A cue that someone might leave, withdraw, or stop caring.'],
    ['P02','Dismissal / invalidation','A sense that your feelings, memory, or needs are being minimized.'],
    ['P03','Control / autonomy','Being ordered, cornered, controlled, or denied choice.'],
    ['P04','Unfairness / double standard','Rules, consequences, or expectations feel unequal.'],
    ['P05','Blame and shame','Expecting criticism, humiliation, or being made responsible for everything.'],
    ['P06','Boundary intrusion','Personal space, privacy, time, or a clear limit is crossed.'],
    ['P07','Unpredictable warmth','Care or affection feels conditional, inconsistent, or withdrawn.'],
    ['P08','Obligation / guilt','Pressure to caretake or put others ahead of your own needs.'],
    ['P09','Emotional escalation','Raised voices, conflict, threats, or intense reactions feel unsafe.'],
    ['P10','Being misunderstood','Fear someone has decided what you mean without asking.'],
    ['P11','Trust / betrayal','Information, promises, or vulnerabilities may not be safe with someone.'],
    ['P12','Feeling trapped','No clear escape, rest, permission, or realistic choice.'],
    ['P13','Rejection sensitivity','Small differences or delays feel like a personal rejection.'],
    ['P14','Protective isolation','An urge to leave, shut down, go numb, or stop explaining.'],
    ['P15','Conflicting loyalty','Caring for someone while needing protection from them.'],
    ['P16','Unexpected change','Plans or routines shift and your system goes on alert.']
  ];
  const SERIES = [
    {code:'100',title:'Present event',desc:'What happened now, separated from what it might mean.'},
    {code:'200',title:'Memory echo',desc:'The past association or internal story the event awakened.'},
    {code:'300',title:'Pressure point',desc:'The recurring theme that makes the moment feel charged.'},
    {code:'400',title:'Protective strategy',desc:'What your body wanted to do and what you actually did.'},
    {code:'500',title:'Impact & repair',desc:'Effects on yourself and others, plus a fair next step.'},
    {code:'600',title:'Trust evidence',desc:'Observed behaviour over time, separate from diagnoses or promises.'}
  ];
  const EPISODE_FIELDS = ['title','when','person','presentEvent','emotions','intensity','body','firstMeaning','memoryHook','associationTrail','rootIds','memoryConfidence','tagIds','protectiveUrge','actualResponse','impact','need','boundary','uncertainty','appraisal','counterEvidence','unknowns','chosenResponse','repair','outcome','reviewDate'];
  const timeNow = () => new Date().toISOString();
  const id = () => (crypto.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const escapeHTML = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const text = escapeHTML;
  const short = (value,length=130)=>{const s=String(value||'');return escapeHTML(s.length>length?s.slice(0,length-1)+'…':s)};
  const dateString = value => {const d=new Date(value);return isNaN(d.getTime())?'Undated':d.toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})};
  const dateTimeLocal = value => {const d=new Date(value);if(isNaN(d.getTime()))return '';const x=new Date(d.getTime()-d.getTimezoneOffset()*60000);return x.toISOString().slice(0,16)};
  const fromLocal = value => value ? new Date(value).toISOString() : timeNow();
  const arr = value => Array.isArray(value)?value:[];
  const clamp = (n,min,max) => Math.max(min,Math.min(max,Number(n)||0));
  const group = (items,key) => items.reduce((o,x)=>{const k=key(x);o[k]=(o[k]||0)+1;return o},{});
  const top = (obj,n) => Object.entries(obj).sort((a,b)=>b[1]-a[1]).slice(0,n);
  const episodeBlank = () => ({id:null,status:'draft',createdAt:timeNow(),updatedAt:timeNow(),title:'',when:timeNow(),person:'',presentEvent:'',emotions:[],intensity:5,body:'',firstMeaning:'',memoryHook:'',associationTrail:'',rootIds:[],memoryConfidence:'uncertain',tagIds:[],protectiveUrge:'',actualResponse:'',impact:'',need:'',boundary:'',uncertainty:'',appraisal:'unassessed',counterEvidence:'',unknowns:'',chosenResponse:'',repair:'',outcome:'',reviewDate:''});
  const freshState = () => ({version:SCHEMA_VERSION,episodes:[],roots:[],trust:[],tags:TAXONOMY.map(t=>({id:t[0],name:t[1],description:t[2],createdAt:timeNow()})),draft:episodeBlank(),settings:{welcomeSeen:false}});
  const normalize = raw => {
    if(!raw||typeof raw!=='object'||raw.version!==SCHEMA_VERSION||!Array.isArray(raw.episodes)||!Array.isArray(raw.roots)||!Array.isArray(raw.trust)||!Array.isArray(raw.tags))throw new Error('Unrecognized backup format or schema version.');
    if(raw.episodes.length>20000||raw.roots.length>10000||raw.trust.length>20000||raw.tags.length>2000)throw new Error('Backup contains an unusually large collection.');
    const cleanRows = value => arr(value).filter(x=>x&&typeof x==='object'&&!Array.isArray(x)).map(x=>({...x}));
    const out={version:SCHEMA_VERSION,episodes:cleanRows(raw.episodes),roots:cleanRows(raw.roots),trust:cleanRows(raw.trust),tags:cleanRows(raw.tags),draft:raw.draft&&typeof raw.draft==='object'?{...episodeBlank(),...raw.draft}:episodeBlank(),settings:{welcomeSeen:Boolean(raw.settings?.welcomeSeen)}};
    for(const e of out.episodes){e.tagIds=arr(e.tagIds).filter(x=>typeof x==='string');e.rootIds=arr(e.rootIds).filter(x=>typeof x==='string');e.emotions=arr(e.emotions).filter(x=>typeof x==='string');e.intensity=clamp(e.intensity,0,10);}
    out.draft.tagIds=arr(out.draft.tagIds);out.draft.rootIds=arr(out.draft.rootIds);out.draft.emotions=arr(out.draft.emotions);
    return out;
  };
  const pageTitle = {home:['FILE PLAN / OVERVIEW','An archive, not a verdict.'],stage:['INTAKE / CURRENT EMOTION','Stage the feeling. Find the thread.'],archive:['RECORD SERIES / ALL ENTRIES','Your emotional archive.'],origins:['SERIES 200 / THE PAST','Origins and early lessons.'],atlas:['CLASSIFICATION / CONNECTIONS','Your pressure-point atlas.'],trust:['SERIES 600 / OBSERVATIONS','Trust is built from evidence.'],insights:['TRENDS / REVIEW','See the pattern, not just the moment.'],data:['OWNERSHIP / PORTABILITY','Your records, your control.']};
  let state = freshState();
  let ui = {page:'home',step:0,archiveQuery:'',archiveStatus:'all',archivePerson:'all',archiveTag:'all',mapTag:'all',mapSelection:null,originEdit:null,trustEdit:null,tagEdit:null,trustPerson:'all',insightPeriod:'all'};
  let saveChain=Promise.resolve(),draftTimer=null,toastTimer=null;
  const screen=document.getElementById('screen');
  const modal=document.getElementById('modal');
  const byTag = value => state.tags.find(t=>t.id===value);
  const byRoot = value => state.roots.find(r=>r.id===value);
  const badge = (label,kind='') => `<span class="badge ${kind}">${text(label)}</span>`;
  const tagPills = tagIds => arr(tagIds).map(t=>byTag(t)).filter(Boolean).map(t=>badge(t.name)).join(' ');
  const trustLabel = evidence => ({honored:'Boundary respected',crossed:'Boundary crossed',mixed:'Mixed / unclear',unknown:'Not enough information'})[evidence]||'Not assessed';
  const trustSignal = evidence => `<span class="trust-signal ${text(evidence||'unknown')}">${text(trustLabel(evidence))}</span>`;
  const field = (name,label,placeholder='',rows=0,help='')=>`<div class="field"><label for="${name}">${label}${help?`<small>${help}</small>`:''}</label>${rows?`<textarea id="${name}" name="${name}" rows="${rows}" placeholder="${text(placeholder)}">${text(state.draft[name]||'')}</textarea>`:`<input id="${name}" name="${name}" placeholder="${text(placeholder)}" value="${text(state.draft[name]||'')}" maxlength="4000">`}</div>`;

  async function persist(announce=false){
    const snap=structuredClone(state);
    document.getElementById('save-state').textContent='Saving locally…';
    saveChain=saveChain.catch(()=>{}).then(()=>STORE.set(snap)).then(()=>{document.getElementById('save-state').textContent='✓ Saved on this device';if(announce)toast('Saved on this device.');}).catch(error=>{document.getElementById('save-state').textContent='⚠ Not saved';toast(`Save failed: ${error.message}`)});
    return saveChain;
  }
  function queueDraft(){clearTimeout(draftTimer);draftTimer=setTimeout(()=>persist(),450)}
  function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3400)}
  function navigate(page){if(!pageTitle[page])return;clearTimeout(draftTimer);if(ui.page==='stage')persist();ui.page=page;history.replaceState(null,'',`#${page}`);window.scrollTo({top:0,behavior:'instant'});render()}
  function render(){const [kick,title]=pageTitle[ui.page];document.getElementById('view-kicker').textContent=kick;document.getElementById('view-title').textContent=title;document.querySelectorAll('[data-nav]').forEach(el=>{const active=el.dataset.nav===ui.page;el.classList.toggle('active',active);if(active)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});screen.innerHTML=({home:homeView,stage:stageView,archive:archiveView,origins:originsView,atlas:atlasView,trust:trustView,insights:insightsView,data:dataView})[ui.page]();}
  function showModal(html){document.getElementById('modal-body').innerHTML=html;modal.showModal()}
  function closeModal(){if(modal.open)modal.close()}
  function iconStat(value,label){return `<div class="metric"><strong>${value}</strong><small>${text(label)}</small></div>`}
  function sectionTitle(title,detail=''){return `<div class="section-header"><h2>${title}</h2>${detail?`<span>${detail}</span>`:''}</div>`}

  function homeView(){
    const committed=state.episodes.filter(e=>e.status==='committed');const staged=state.episodes.filter(e=>e.status==='staged');
    const freq=group(committed.flatMap(e=>arr(e.tagIds)),x=>x);const frequent=top(freq,6);
    return `<div class="grid-main"><section class="card hero"><div><div class="overline">SELF-OBSERVATION / WITHOUT A PREWRITTEN CONCLUSION</div><h2>Find where a feeling came from. Decide where it goes next.</h2><p>An emotional reaction can contain a real present-day problem, an old survival lesson, and an action you want to own—all at once.</p><button class="btn dark" data-nav="stage">Open a new intake →</button></div></section><div class="flow"><section class="card"><div class="overline">YOUR FILE PLAN</div><h2>Six destinations, one clearer picture.</h2><div class="metric-line">${iconStat(committed.length,'Committed')}${iconStat(staged.length,'Staged')}${iconStat(state.roots.length,'Origins')}</div><div class="divider"></div><div class="classification" style="padding-top:0"><span class="series-code">200</span><div><strong>The memory behind the alarm</strong><p>A past experience is context—not proof about the person in front of you.</p></div><span class="count">${state.roots.length}</span></div><div class="classification"><span class="series-code">500</span><div><strong>My impact and a fair repair</strong><p>Understand the feeling while choosing responsibility for behaviour.</p></div><span class="count">${committed.length}</span></div><button class="btn inkless" data-nav="archive">Open record series →</button></section><section class="card"><div class="overline">A REFLECTION PROMPT</div><h3>What is present? What is remembered?</h3><p>Keep those two answers separate before deciding what is fair to ask of someone now.</p></section></div></div>
    ${sectionTitle('Your filing architecture','An adaptable record series')}
    <div class="grid-thirds">${SERIES.map(s=>`<div class="card"><div class="overline">SERIES ${s.code}</div><h3>${s.title}</h3><p>${s.desc}</p></div>`).join('')}</div>
    <div class="grid-halves" style="margin-top:18px"><section class="card"><div class="flex-between"><h2>Recurring pressure points</h2><button class="btn inkless small" data-nav="atlas">Open atlas →</button></div>${frequent.length?`<div class="cloud">${frequent.map(([k,n])=>{const t=byTag(k);return t?`<button data-action="filter-tag" data-tag="${text(k)}" style="font-size:${Math.min(29,15+n*2)}px" title="${n} records">${text(t.name)}</button>`:''}).join('')}</div>`:`<div class="empty"><span class="empty-icon">✳</span>Your most common themes will become visible as you add records.</div>`}</section><section class="card"><div class="flex-between"><h2>Recent records</h2><button class="btn inkless small" data-nav="archive">See all →</button></div>${state.episodes.length?`<div class="record-list">${[...state.episodes].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).slice(0,3).map(e=>episodeRow(e,false)).join('')}</div>`:'<div class="empty">This is a blank archive. Start with a current emotion or a memory you already understand.</div>'}</section></div>
    <div class="spacer"></div><div class="notice"><div><strong>Why this does not give you a “warranted / unwarranted” score</strong><p>Your feeling can be understandable. Your interpretation can still be incomplete. And your action can still need repair. The app keeps those truths separate.</p></div><button class="btn light" data-action="about-framework">Read the framework</button></div>`;
  }

  function stageView(){
    const steps=[['01','Present'],['02','Echo'],['03','Protection'],['04','End point']];const d=state.draft;const edit=d.id?`Editing ${text(d.title||'record')}`:'New reaction intake';
    return `<p class="page-note">Begin with what happened. Follow the associations without forcing memories. Keep what you know, what you infer, and what you choose in different places. Every entry can be staged now and completed later.</p><div class="grid-main"><div><div class="stage-progress">${steps.map((s,i)=>`<button data-action="step" data-step="${i}" class="${ui.step===i?'current':i<ui.step?'past':''}" aria-current="${ui.step===i?'step':'false'}"><b>${s[0]}</b>${s[1]}</button>`).join('')}</div><section class="card stage-card"><div class="flex-between"><span class="overline">${edit}</span><span class="badge ${d.id?'orange':''}">${d.status==='staged'?'Resuming staged':'Autosaved draft'}</span></div><div class="spacer-sm"></div><form id="episode-form">${[stepPresent,stepEcho,stepProtection,stepCommit][ui.step]()}<div class="stage-footer"><div class="pill-row"><button class="btn border" type="button" data-action="stage-save">Stage for later</button><button class="btn inkless" type="button" data-action="new-intake">Clear intake</button></div><div class="pill-row">${ui.step>0?'<button class="btn border" type="button" data-action="step-back">← Back</button>':''}${ui.step<3?'<button class="btn dark" type="button" data-action="step-next">Continue →</button>':'<button class="btn dark" type="button" data-action="commit">Commit to archive ↗</button>'}</div></div></form></section></div><div class="flow"><section class="card"><div class="overline">WHERE THIS IS GOING</div><h2>From alarm to agency.</h2><div class="series-map">${SERIES.slice(0,5).map(s=>`<div class="series-map-row"><span>${s.code}</span><div><strong>${s.title}</strong><p>${s.desc}</p></div></div>`).join('')}</div></section><div class="soft-panel warm"><strong>Permission to stop.</strong><br>If your body is overwhelmed, stage what you have and leave. A partial record is enough. You don't have to relive a memory to use this system.</div></div></div>`;
  }
  function stepPresent(){const d=state.draft;return `<h2>100 / Name the event</h2><p class="stage-intro">Record what happened in the present, before interpreting motives. Quick captures are welcome.</p><div class="fields-2"><div class="field"><label for="title">A short file title</label><input name="title" id="title" maxlength="120" placeholder="The cancelled plan" value="${text(d.title)}"></div><div class="field"><label for="when">When did this happen?</label><input type="datetime-local" name="when" id="when" value="${text(dateTimeLocal(d.when))}"></div></div><div class="field"><label for="person">Who was involved?</label><select name="person" id="person"><option value="">Choose a relationship…</option>${RELATIONSHIPS.map(x=>`<option value="${text(x)}" ${d.person===x?'selected':''}>${x}</option>`).join('')}</select></div>${field('presentEvent','What could a camera or recording verify?','What was said, done, or changed? Avoid guessing why.',4,'Describe the observable event, not a verdict about intent.')}<div class="field"><span class="field-label">What emotions are here?</span><div class="checks">${EMOTIONS.map(x=>`<label class="check-pill"><input type="checkbox" name="emotions" value="${x}" ${arr(d.emotions).includes(x)?'checked':''}><span>${x}</span></label>`).join('')}</div></div><div class="field"><label for="intensity">How strong is the feeling right now?</label><div class="field-range"><input id="intensity" type="range" name="intensity" min="0" max="10" value="${clamp(d.intensity,0,10)}"><output id="intensity-output">${clamp(d.intensity,0,10)}</output></div><div id="distress-note" class="soft-panel warm ${Number(d.intensity)>=8?'':'hidden'}" style="margin-top:12px">High intensity is a reason to pause, not to push deeper. Reach out to someone safe. If you're at risk of harming yourself, call or text 988 in Canada, or 911 in immediate danger.</div></div>${field('body','What did your body do?','Tight chest, heat, numbness, restlessness, tiredness…',2)}`}
  function stepEcho(){const d=state.draft;return `<h2>200 / Follow the echo</h2><p class="stage-intro">A present cue can light up an older memory or expectation. The association may be automatic—even when the connection is weak or incomplete.</p>${field('firstMeaning','What did my brain say this meant?','“I am not important.” “I am about to be blamed.”',3)}${field('memoryHook','What earlier situation, if any, did this resemble?','A familiar tone, silence, rule, expression, or memory…',3,'You can write “unknown.” Do not search for a memory that is not there.')}<div class="field"><label for="associationTrail">The associative detour <small>One thought or memory per line, in order. Example: delayed text → being ignored → mother leaving during an argument.</small></label><textarea name="associationTrail" id="associationTrail" rows="4" placeholder="Today’s cue&#10;The first mental leap&#10;Another adjacent thought&#10;The memory I landed on">${text(d.associationTrail)}</textarea></div><div class="field"><span class="field-label">Link an origin record (optional)</span>${state.roots.length?state.roots.map(r=>`<label class="origin-option"><input type="checkbox" name="rootIds" value="${text(r.id)}" ${arr(d.rootIds).includes(r.id)?'checked':''}><span><strong>${text(r.title)}</strong><small>${text(r.period||'Earlier experience')} · ${text(r.source||'Personal account')}</small></span></label>`).join(''):'<div class="soft-panel">Your origin library is empty. You can still continue. Add a remembered lesson later and link this record then.</div>'}</div><div class="field"><label for="memoryConfidence">How certain am I about this link?</label><select name="memoryConfidence" id="memoryConfidence">${[['uncertain','I am not sure'],['clear','Clear connection in my own memory'],['possible','A possible connection / inference'],['none','No past connection identified']].map(x=>`<option value="${x[0]}" ${d.memoryConfidence===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div>`}
  function stepProtection(){const d=state.draft;return `<h2>300–500 / Pressure, protection, impact</h2><p class="stage-intro">Your nervous system may try to protect you. That strategy can make sense historically and still create unfairness in the present.</p><div class="field"><span class="field-label">Which pressure points were activated?</span><p class="tiny quiet mt-0">Multiple labels are allowed. These link your entries into the atlas.</p><div class="tag-picker">${state.tags.map(t=>`<button type="button" class="tag-button ${arr(d.tagIds).includes(t.id)?'selected':''}" data-action="toggle-draft-tag" data-tag="${text(t.id)}" aria-pressed="${arr(d.tagIds).includes(t.id)}">${text(t.name)}</button>`).join('')}</div></div><div class="spacer-sm"></div>${field('protectiveUrge','What did I feel driven to do?','Attack, explain, withdraw, control, chase reassurance, leave, shut down…',3)}${field('actualResponse','What did I actually do or say?','Be specific. Include what I did well and what I regret.',3)}${field('impact','What effect might my response have had on me or others?','Who was affected? What do I know? What am I guessing?',3)}${field('need','What real need was I trying to meet?','Safety, clarity, autonomy, fairness, closeness, rest…',2)}${field('boundary','What would a fair boundary or request look like?','A limit I control, or a request someone can freely answer.',3)}${field('uncertainty','What could I be missing?', 'Alternative interpretations, another person’s circumstances, incomplete information…',3)}`}
  function stepCommit(){const d=state.draft;return `<h2>500 / Choose an end point</h2><p class="stage-intro">This is not an automatic “right or wrong” judgment. You decide what is known, what still needs checking, and what response fits your values.</p><div class="field"><label for="appraisal">My working assessment of the present event</label><select name="appraisal" id="appraisal">${[['unassessed','Not assessed / still overwhelmed'],['clear-boundary','A present-day boundary or need was clearly affected'],['mixed','Both a real issue and an old echo may be present'],['echo','The reaction seems amplified by a memory echo'],['unknown','I need more evidence before deciding']].map(x=>`<option value="${x[0]}" ${d.appraisal===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div>${field('counterEvidence','What evidence challenges my first interpretation?','What did the person actually do? When have things gone differently?',3)}${field('unknowns','What remains unknown or needs a conversation?','Intentions, context, impact, whether a boundary was understood…',3)}${field('chosenResponse','What is one response I want to commit to?','Pause, state a limit, ask a question, make amends, choose distance…',3)}${field('repair','Do I owe anyone a repair? Do I need a repair from them?','An apology, changed behaviour, acknowledgment, or no repair needed.',3)}${field('outcome','What happened afterward (if known)?','Leave blank if the story is still unfolding.',2)}<div class="field"><label for="reviewDate">Optional revisit date</label><input type="date" id="reviewDate" name="reviewDate" value="${text(d.reviewDate)}"></div><div class="soft-panel"><strong>End point:</strong> A committed entry is a snapshot of your understanding today. You can reopen it, add new evidence, and revise your conclusion without erasing your earlier perspective.</div>`}

  function episodeRow(e,showActions=true){
    const tag=arr(e.tagIds).map(byTag).find(Boolean);const label=e.status==='committed'?'Committed':'Staged';
    return `<article class="record-row"><div class="record-content"><div class="record-date">${dateString(e.when||e.createdAt)} · ${text(e.person||'Unassigned relationship')}</div><strong>${text(e.title||'Untitled record')}</strong><div class="pill-row" style="margin-top:8px">${badge(label,e.status==='staged'?'orange':'')}${tag?badge(tag.name):''}${badge(`${clamp(e.intensity,0,10)}/10`,'blue')}</div><p>${short(e.presentEvent||e.firstMeaning||'A record waiting to be processed.',170)}</p></div><div class="record-actions"><button class="btn border small" data-action="view-episode" data-id="${text(e.id)}">Review</button>${showActions?`<button class="btn light small" data-action="edit-episode" data-id="${text(e.id)}">Edit</button>`:''}</div></article>`;
  }
  function archiveFiltered(){return [...state.episodes].filter(e=>{
    if(ui.archiveStatus!=='all'&&e.status!==ui.archiveStatus)return false;
    if(ui.archivePerson!=='all'&&e.person!==ui.archivePerson)return false;
    if(ui.archiveTag!=='all'&&!arr(e.tagIds).includes(ui.archiveTag))return false;
    if(ui.archiveQuery.trim()){
      const q=ui.archiveQuery.trim().toLowerCase();const haystack=[e.title,e.person,e.presentEvent,e.firstMeaning,e.memoryHook,e.associationTrail,e.protectiveUrge,e.actualResponse,e.impact,e.chosenResponse,e.repair].join(' ').toLowerCase();if(!haystack.includes(q))return false;
    }
    return true;
  }).sort((a,b)=>new Date(b.when||b.createdAt)-new Date(a.when||a.createdAt));}
  function archiveView(){const entries=archiveFiltered();return `<p class="page-note">Each record can contain more than one pressure point or origin. Review a staged entry when you're ready. Revisions preserve the same record rather than pretending your first impression was final.</p><div class="toolbar"><input id="archive-search" type="search" aria-label="Search your records" placeholder="Search events, thoughts, responses…" value="${text(ui.archiveQuery)}"><select id="archive-status" aria-label="Filter by status"><option value="all">All statuses</option><option value="staged" ${ui.archiveStatus==='staged'?'selected':''}>Staged</option><option value="committed" ${ui.archiveStatus==='committed'?'selected':''}>Committed</option></select><select id="archive-person" aria-label="Filter by relationship"><option value="all">All relationships</option>${RELATIONSHIPS.map(x=>`<option value="${x}" ${ui.archivePerson===x?'selected':''}>${x}</option>`).join('')}</select><select id="archive-tag" aria-label="Filter by pressure point"><option value="all">All pressure points</option>${state.tags.map(t=>`<option value="${text(t.id)}" ${ui.archiveTag===t.id?'selected':''}>${text(t.name)}</option>`).join('')}</select></div><div class="flex-between" style="margin-bottom:16px"><span class="overline">${entries.length} MATCHING FILES / ${state.episodes.length} TOTAL</span><button class="btn dark small" data-nav="stage">+ New intake</button></div><div id="archive-results" class="record-list">${entries.length?entries.map(e=>episodeRow(e)).join(''):'<div class="empty"><span class="empty-icon">▤</span>No matching records. Change a filter or stage a reaction.</div>'}</div>`}
  function episodeDetails(e){const roots=arr(e.rootIds).map(byRoot).filter(Boolean);const labels=[['100 / Present event',e.presentEvent],['Emotions',arr(e.emotions).join(', ')],['Body alarm',e.body],['200 / First interpretation',e.firstMeaning],['Earlier resemblance',e.memoryHook],['Source confidence',e.memoryConfidence],['300 / Pressure points',arr(e.tagIds).map(byTag).filter(Boolean).map(t=>t.name).join(', ')],['400 / Protective urge',e.protectiveUrge],['What I actually did',e.actualResponse],['500 / Impact',e.impact],['The need underneath',e.need],['Fair boundary / request',e.boundary],['What I might be missing',e.uncertainty],['Working assessment',assessmentLabel(e.appraisal)],['Counterevidence',e.counterEvidence],['Still unknown',e.unknowns],['Chosen response',e.chosenResponse],['Repair',e.repair],['Outcome',e.outcome],['Linked origins',roots.map(r=>r.title).join(', ')]];const detour=String(e.associationTrail||'').split('\n').map(x=>x.trim()).filter(Boolean);return `<div class="overline">${dateString(e.when)} / ${text(e.person||'Relationship unspecified')} / ${e.status==='staged'?'STAGED':'COMMITTED'}</div><h2>${text(e.title||'Untitled record')}</h2><div class="pill-row" style="margin-bottom:16px">${badge(`${clamp(e.intensity,0,10)} / 10`,'blue')}${arr(e.emotions).map(x=>badge(x,'orange')).join('')}</div>${detour.length?`<h3 style="font-family:Georgia,serif;font-weight:400">Associative detour</h3><div class="chain">${detour.map((s,i)=>`${i?'<i>→</i>':''}<span>${text(s)}</span>`).join('')}</div>`:''}<div class="details-two">${labels.filter(x=>String(x[1]||'').trim()).map(x=>`<div class="details-pair"><strong>${text(x[0])}</strong><p>${text(x[1])}</p></div>`).join('')}</div><div class="spacer"></div><div class="pill-row"><button class="btn dark" data-action="edit-episode" data-id="${text(e.id)}">Reopen and revise</button><button class="btn border" data-action="delete-episode" data-id="${text(e.id)}">Delete record</button></div>`}
  const assessmentLabel = value => ({unassessed:'Not assessed', 'clear-boundary':'A clear present-day issue','mixed':'Real issue and older echo both possible',echo:'May be amplified by an older association',unknown:'Needs more evidence'})[value]||'Not assessed';

  function originsView(){return `<p class="page-note">Keep a separate record of experiences that may have taught your nervous system what to anticipate. A memory is personal evidence about your experience—not a court finding about anyone's motives. You may also record supportive childhood experiences.</p><div class="notice"><div><strong>Origin does not mean destiny.</strong><p>These records can help you see what a protective strategy once achieved, and whether it still helps now. You never have to invent or recover a memory to complete an intake.</p></div><button class="btn dark" data-action="new-origin">+ Add origin</button></div>${sectionTitle('Origin library',`${state.roots.length} reference records`)}<div class="catalog">${state.roots.length?[...state.roots].sort((a,b)=>new Date(b.updatedAt)-new Date(a.updatedAt)).map(r=>`<article class="catalog-card"><div class="overline">SERIES 200 · ${text(r.period||'EARLIER EXPERIENCE')}</div><h3>${text(r.title)}</h3><p>${short(r.description,185)}</p><p><strong>Learned expectation:</strong> ${short(r.lesson||'Not yet identified',150)}</p><div class="actions"><span class="badge plum">${text(r.source||'Unspecified source')}</span><div class="pill-row"><button class="btn border small" data-action="view-origin" data-id="${text(r.id)}">View</button><button class="btn light small" data-action="edit-origin" data-id="${text(r.id)}">Edit</button></div></div></article>`).join(''):'<div class="empty" style="grid-column:1/-1"><span class="empty-icon">⌁</span>No origins recorded yet. If you prefer, start with present-day events and add origins only when something naturally connects.</div>'}</div><div class="spacer"></div><div class="soft-panel warm"><strong>A note on uncertainty:</strong> Label whether the memory is firsthand, reported by someone else, recorded at the time, or an inference. Allow your interpretation to change when new evidence appears.</div>`}
  function originForm(r){return `<div class="overline">SERIES 200 / ${r?'EDIT ORIGIN':'NEW ORIGIN'}</div><h2>${r?'Revise an origin':'Record an earlier lesson'}</h2><p>Use as much or as little detail as feels safe. You can stop at any point.</p><form id="origin-form" data-id="${text(r?.id||'')}"><div class="field"><label for="origin-title">Reference title</label><input name="title" id="origin-title" maxlength="150" required value="${text(r?.title||'')}" placeholder="When my feelings were dismissed"></div><div class="fields-2"><div class="field"><label for="origin-period">Period of life</label><input name="period" id="origin-period" maxlength="120" value="${text(r?.period||'')}" placeholder="Early childhood / age 16 / unknown"></div><div class="field"><label for="origin-person">Who was involved?</label><input name="person" id="origin-person" maxlength="120" value="${text(r?.person||'')}" placeholder="Mother, caregiver, school…"></div></div><div class="field"><label for="origin-desc">What I remember or know happened</label><textarea name="description" id="origin-desc" rows="4" maxlength="6000" placeholder="What happened, to the extent I know…">${text(r?.description||'')}</textarea></div><div class="field"><label for="origin-lesson">What did I learn to anticipate or do to stay safe?</label><textarea name="lesson" id="origin-lesson" rows="3" maxlength="4000" placeholder="Stay quiet, explain myself quickly, watch people’s moods…">${text(r?.lesson||'')}</textarea></div><div class="field"><label for="origin-source">Source of this account</label><select name="source" id="origin-source">${[['firsthand','My own memory'],['written','Contemporaneous record'],['told','Someone told me'],['inferred','An inference / hypothesis'],['unsure','Not sure']].map(x=>`<option value="${x[0]}" ${r?.source===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field"><label for="origin-today">What do I want to remember about it now?</label><textarea name="today" id="origin-today" rows="3" maxlength="4000" placeholder="A fairer belief, something I know now, a boundary I need…">${text(r?.today||'')}</textarea></div><button class="btn dark" type="submit">Save origin</button></form>`}
  function originDetails(r){const connected=state.episodes.filter(e=>arr(e.rootIds).includes(r.id));return `<div class="overline">SERIES 200 · ${text(r.period||'EARLIER EXPERIENCE')}</div><h2>${text(r.title)}</h2><div class="details-pair"><strong>Who was involved</strong><p>${text(r.person||'Not recorded')}</p></div><div class="details-pair"><strong>Account</strong><p>${text(r.description||'Not recorded')}</p></div><div class="details-pair"><strong>Learned expectation</strong><p>${text(r.lesson||'Not identified')}</p></div><div class="details-pair"><strong>What I know now</strong><p>${text(r.today||'Still exploring')}</p></div><div class="details-pair"><strong>Source type</strong><p>${text(r.source||'Unspecified')}</p></div><div class="details-pair"><strong>Connected recent records</strong><p>${connected.map(e=>e.title||'Untitled').map(text).join(', ')||'None yet'}</p></div><div class="pill-row"><button class="btn dark" data-action="edit-origin" data-id="${text(r.id)}">Edit</button><button class="btn border" data-action="delete-origin" data-id="${text(r.id)}">Delete origin</button></div>`}

  function atlasView(){const count=group(state.episodes.flatMap(e=>arr(e.tagIds)),x=>x);const cloudTags=[...state.tags].sort((a,b)=>(count[b.id]||0)-(count[a.id]||0));const selected=ui.mapTag==='all'?state.episodes:state.episodes.filter(e=>arr(e.tagIds).includes(ui.mapTag));return `<p class="page-note">A functional classification system. Labels act as destinations, while each record can live under several pressure points and be linked to more than one origin. Click a word to see the evidence behind it.</p><div class="grid-halves"><section class="card"><div class="flex-between"><div><div class="overline">FUNCTIONAL WORD CLOUD</div><h2>Your recurring themes</h2></div><button class="btn border small" data-action="clear-map">Clear filter</button></div><div class="cloud">${cloudTags.map((t,i)=>`<button title="${count[t.id]||0} linked records" aria-pressed="${ui.mapTag===t.id}" class="${ui.mapTag===t.id?'active':''}" data-action="select-map-tag" data-tag="${text(t.id)}" style="font-size:${Math.min(31,15+(count[t.id]||0)*3+(i<4?2:0))}px">${text(t.name)}</button>`).join('')}</div><div class="soft-panel"><strong>Word size = frequency of linked records.</strong> It does not measure how serious a memory is or how responsible someone was.</div></section><section class="card"><div class="overline">CLASSIFICATION DESTINATION</div><h2>${ui.mapTag==='all'?'Choose a pressure point':text(byTag(ui.mapTag)?.name||'Unidentified pressure point')}</h2>${ui.mapTag==='all'?'<p>Select a word to view the episodes connected to it, or use the relationship map below.</p>':`<p>${text(byTag(ui.mapTag)?.description||'Your custom label')}</p><div class="badge orange">${selected.length} linked records</div>`}<div class="spacer-sm"></div><div class="record-list">${selected.length?selected.slice(-4).reverse().map(e=>episodeRow(e,false)).join(''):'<div class="empty">No records linked yet.</div>'}</div><div class="spacer-sm"></div><button class="btn light" data-action="open-tag-archive">View matching archive →</button></section></div>
    ${sectionTitle('Connection map','Origins → pressure points → present records')}
    <section class="card"><div class="key-legend"><span><i class="legend-dot" style="background:#9d82a1"></i>Origin records</span><span><i class="legend-dot" style="background:#d4a26e"></i>Pressure points</span><span><i class="legend-dot" style="background:#6f9f88"></i>Recent episodes</span></div><div class="map-scroll">${graphSVG()}</div><p class="tiny quiet">The map displays up to eight nodes per column to keep labels legible. The word cloud and archive include every entry. Lines show links you entered, not an inferred cause.</p></section>
    ${sectionTitle('Manage destinations','Your file plan can grow')}
    <div class="grid-halves"><section class="card"><h3>Add your own pressure point</h3><p>Keep the wording concrete. You can add new labels without having to choose from a clinical list.</p><form id="tag-form"><div class="field"><label for="new-tag">Name</label><input required maxlength="85" name="name" id="new-tag" placeholder="For example: being called selfish"></div><div class="field"><label for="new-tag-desc">Meaning (optional)</label><textarea name="description" id="new-tag-desc" maxlength="350" rows="2" placeholder="What this recurring pressure point represents"></textarea></div><button class="btn dark" type="submit">Add destination</button></form></section><section class="card"><h3>Classification notes</h3><p>Use fewer labels when they mean the same thing. Use several labels when one event genuinely spans several themes. This is an evolving filing system, not a fixed map of your personality.</p><div class="soft-panel warm">Each record carries its own facts and uncertainty. A shared pressure-point label means an association you noticed, not proof of one cause.</div></section></div>`}
  function graphSVG(){
    const episodes=[...state.episodes].sort((a,b)=>new Date(b.when)-new Date(a.when)).slice(0,8);
    const tagIds=[...new Set(episodes.flatMap(e=>arr(e.tagIds)))].slice(0,8);
    const rootIds=[...new Set(episodes.flatMap(e=>arr(e.rootIds)))].slice(0,8);
    if(!episodes.length)return '<div class="empty"><span class="empty-icon">✳</span>The connection map appears after you file records under pressure points or origins.</div>';
    const col={root:28,tag:354,episode:681},w=230,h=37,height=Math.max(380,Math.max(rootIds.length,tagIds.length,episodes.length)*61+72);
    const layout=(ids,x)=>new Map(ids.map((v,i)=>[v,{x,y:65+i*(height-120)/Math.max(ids.length,1)}]));
    const originPos=layout(rootIds,col.root),tagPos=layout(tagIds,col.tag),episodePos=layout(episodes.map(x=>x.id),col.episode);
    let edges='';for(const e of episodes){const ep=episodePos.get(e.id);for(const t of arr(e.tagIds)){const tp=tagPos.get(t);if(tp)edges+=`<path d="M${tp.x+w} ${tp.y+h/2} C${tp.x+w+45} ${tp.y+h/2},${ep.x-50} ${ep.y+h/2},${ep.x} ${ep.y+h/2}" fill="none" stroke="#d2c9b7" stroke-width="1.5"/>`};for(const r of arr(e.rootIds)){const rp=originPos.get(r);if(!rp)continue;for(const t of arr(e.tagIds)){const tp=tagPos.get(t);if(tp)edges+=`<path d="M${rp.x+w} ${rp.y+h/2} C${rp.x+w+52} ${rp.y+h/2},${tp.x-54} ${tp.y+h/2},${tp.x} ${tp.y+h/2}" fill="none" stroke="#d8d1db" stroke-width="1.3"/>`}}}
    const node=(pos,label,colour,type,idValue)=>`<g class="svg-node" tabindex="0" role="button" data-action="map-node" data-type="${type}" data-id="${text(idValue)}" aria-label="Open ${text(type)} ${text(label)}"><rect x="${pos.x}" y="${pos.y}" width="${w}" height="${h}" rx="9" fill="${colour}"/><text x="${pos.x+13}" y="${pos.y+23}" font-size="12" fill="#28413e">${short(label,29)}</text></g>`;
    const nodes=[...originPos.entries()].map(([rid,p])=>node(p,byRoot(rid)?.title||'Origin','#eee7f1','origin',rid)).join('')+[...tagPos.entries()].map(([tid,p])=>node(p,byTag(tid)?.name||'Pressure point','#f5e5cc','tag',tid)).join('')+episodes.map(e=>node(episodePos.get(e.id),e.title||'Untitled event','#e3eee6','episode',e.id)).join('');
    return `<svg class="svg-map" viewBox="0 0 960 ${height}" role="img" aria-label="Connections between stored origins, pressure points, and emotional episodes"><text x="28" y="35" font-size="11" font-weight="700" letter-spacing="1.5" fill="#9c83a5">200 / ORIGINS</text><text x="354" y="35" font-size="11" font-weight="700" letter-spacing="1.5" fill="#b68c56">300 / PRESSURE POINTS</text><text x="681" y="35" font-size="11" font-weight="700" letter-spacing="1.5" fill="#78a28b">100 / PRESENT</text>${edges}${nodes}</svg>`;
  }

  function trustView(){const all=[...state.trust].sort((a,b)=>new Date(b.when)-new Date(a.when));const entries=ui.trustPerson==='all'?all:all.filter(x=>x.person===ui.trustPerson);const evidence=group(entries,x=>x.evidence||'unknown');return `<p class="page-note">Record what a person actually did when you expressed a need, set a boundary, or brought up harm. Include respectful behaviour and meaningful repair as well as disappointments. A diagnosis cannot tell you whether an individual is safe to trust.</p><div class="notice"><div><strong>Familiarity is not the same as safety.</strong><p>Evidence of growth might include listening without punishment, acknowledging harm, changed behaviour, and respecting the same boundary repeatedly—not merely promising to change.</p></div><button class="btn dark" data-action="new-trust">+ Log an interaction</button></div><div class="spacer"></div><div class="toolbar"><select id="trust-person" aria-label="Filter trust observations"><option value="all">All people</option>${[...new Set([...state.trust.map(x=>x.person), 'Mother'])].filter(Boolean).map(x=>`<option value="${text(x)}" ${ui.trustPerson===x?'selected':''}>${text(x)}</option>`).join('')}</select><span class="quiet tiny">These are observations, not a trust score.</span></div><div class="snapshot"><div class="card"><strong>${evidence.honored||0}</strong><p>Boundaries respected</p></div><div class="card"><strong>${evidence.crossed||0}</strong><p>Boundaries crossed</p></div><div class="card"><strong>${(evidence.mixed||0)+(evidence.unknown||0)}</strong><p>Mixed or uncertain</p></div></div>${sectionTitle('Evidence over time',`${entries.length} observations`)}<div class="timeline">${entries.length?entries.map(t=>`<article class="card timeline-item"><div class="flex-between wrap"><div><div class="record-date">${dateString(t.when)} · ${text(t.person||'Person unspecified')}</div><strong>${text(t.title||'Interaction')}</strong></div>${trustSignal(t.evidence)}</div><p><strong>Observed:</strong> ${short(t.behavior||'Not recorded',300)}</p>${t.boundary?`<p><strong>My boundary:</strong> ${short(t.boundary,300)}</p>`:''}${t.repair?`<p><strong>Repair:</strong> ${short(t.repair,300)}</p>`:''}<div class="pill-row"><button class="btn border small" data-action="view-trust" data-id="${text(t.id)}">Review</button><button class="btn light small" data-action="edit-trust" data-id="${text(t.id)}">Edit</button></div></article>`).join(''):'<div class="empty"><span class="empty-icon">◇</span>No trust observations yet. You can record a good interaction, a harmful one, or an uncertain one.</div>'}</div><div class="spacer"></div><div class="soft-panel violet"><strong>A reflection for contact with family:</strong> What behaviour would make a visit safe enough? What boundary is under my control if it isn't respected? What would count as sustained change, across several interactions?</div>`}
  function trustForm(t){return `<div class="overline">SERIES 600 / ${t?'EDIT EVIDENCE':'NEW OBSERVATION'}</div><h2>Track an observable interaction</h2><p>This is evidence about behaviour, not a diagnosis or an assessment of character.</p><form id="trust-form" data-id="${text(t?.id||'')}"><div class="fields-2"><div class="field"><label for="trust-title">Short title</label><input required id="trust-title" name="title" maxlength="140" value="${text(t?.title||'')}" placeholder="A visit with my siblings"></div><div class="field"><label for="trust-when">Date</label><input type="date" id="trust-when" name="when" value="${text((t?.when||timeNow()).slice(0,10))}"></div></div><div class="field"><label for="trust-name">Person</label><input required id="trust-name" name="person" maxlength="120" value="${text(t?.person||'Mother')}" placeholder="Mother"></div><div class="field"><label for="trust-behavior">What did I observe, without inferring intent?</label><textarea id="trust-behavior" name="behavior" rows="3" maxlength="5000" placeholder="Words, actions, patterns, tone, follow-through…">${text(t?.behavior||'')}</textarea></div><div class="field"><label for="trust-boundary">What boundary or need did I express?</label><textarea id="trust-boundary" name="boundary" rows="2" maxlength="3000" placeholder="I asked not to be shouted at during the visit…">${text(t?.boundary||'')}</textarea></div><div class="field"><label for="trust-evidence">What happened in relation to that boundary?</label><select name="evidence" id="trust-evidence">${[['unknown','Not enough information'],['honored','It was respected'],['mixed','Mixed / partly respected'],['crossed','It was crossed']].map(x=>`<option value="${x[0]}" ${t?.evidence===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></div><div class="field"><label for="trust-repair">Was there acknowledgment, repair, or changed behaviour?</label><textarea name="repair" id="trust-repair" rows="3" maxlength="4000" placeholder="Exact actions over time, not only assurances…">${text(t?.repair||'')}</textarea></div><div class="field"><label for="trust-contact">What conditions would make future contact safe enough?</label><textarea name="contact" id="trust-contact" rows="3" maxlength="4000" placeholder="For example: leave if yelling starts; meet in a public place…">${text(t?.contact||'')}</textarea></div><button class="btn dark" type="submit">Save observation</button></form>`}
  function trustDetails(t){return `<div class="overline">SERIES 600 / ${dateString(t.when)} / ${text(t.person)}</div><h2>${text(t.title)}</h2>${trustSignal(t.evidence)}<div class="spacer"></div>${[['Observed behaviour',t.behavior],['Boundary or need',t.boundary],['Acknowledgment / repair',t.repair],['Future contact conditions',t.contact]].map(x=>`<div class="details-pair"><strong>${text(x[0])}</strong><p>${text(x[1]||'Not recorded')}</p></div>`).join('')}<div class="pill-row"><button class="btn dark" data-action="edit-trust" data-id="${text(t.id)}">Edit</button><button class="btn border" data-action="delete-trust" data-id="${text(t.id)}">Delete observation</button></div>`}

  function insightsView(){const committed=state.episodes.filter(e=>e.status==='committed');const count=group(committed.flatMap(e=>arr(e.tagIds)),x=>x);const popular=top(count,9);const review=committed.filter(e=>e.reviewDate&&e.reviewDate<=timeNow().slice(0,10));return `<p class="page-note">Use these summaries to spot themes across months or years. Frequency does not prove causation, wrongdoing, or a person's motives. The most important shift may be one you notice in the way you respond.</p><div class="snapshot"><div class="card"><strong>${committed.length}</strong><p>Completed emotional records</p></div><div class="card"><strong>${state.roots.length}</strong><p>Origin references</p></div><div class="card"><strong>${review.length}</strong><p>Records due to revisit</p></div></div><div class="spacer"></div><div class="grid-halves"><section class="card"><h2>Intensity over time</h2><p>Latest 20 committed entries, using the intensity you recorded. High numbers don't mean failure.</p><div class="chart-wrap">${intensityGraph(committed)}</div></section><section class="card"><h2>Most-used pressure points</h2>${popular.length?`<div class="bar-stack">${popular.map(([k,n])=>{const t=byTag(k);return `<div><div class="bar-label"><span>${text(t?.name||'Archived label')}</span><strong>${n}</strong></div><div class="bar-track"><span style="width:${Math.round(n/popular[0][1]*100)}%"></span></div></div>`}).join('')}</div>`:'<div class="empty">Your strongest recurring themes will become visible over time.</div>'}</section></div>${sectionTitle('Questions worth revisiting','No automatic judgment')}
    <div class="grid-thirds"><section class="card"><div class="overline">WHAT WAS REAL?</div><h3>Present evidence</h3><p>How often was the boundary clear? How often was the situation ambiguous, or missing context?</p><div class="bar-stack">${['clear-boundary','mixed','echo','unknown'].map(k=>{const n=committed.filter(e=>e.appraisal===k).length;return `<div><div class="bar-label"><span>${text(assessmentLabel(k))}</span><strong>${n}</strong></div><div class="bar-track"><span class="orange" style="width:${Math.round(n/Math.max(1,committed.length)*100)}%"></span></div></div>`}).join('')}</div></section><section class="card"><div class="overline">WHERE DID I GO?</div><h3>Association detours</h3><p>${committed.filter(e=>String(e.associationTrail||'').trim()).length} records trace a chain of thoughts or memories. These chains may help you catch a mood spiral earlier.</p><button class="btn light" data-nav="atlas">Explore connections →</button></section><section class="card"><div class="overline">WHAT CAN CHANGE?</div><h3>Accountability without punishment</h3><p>${committed.filter(e=>String(e.repair||'').trim()).length} records include a possible repair; ${committed.filter(e=>String(e.chosenResponse||'').trim()).length} include a chosen next response.</p><button class="btn light" data-nav="archive">Review your choices →</button></section></div>
    ${review.length?`<div class="spacer"></div><section class="card"><h3>Ready for another look</h3><div class="record-list">${review.map(e=>episodeRow(e,false)).join('')}</div></section>`:''}`}
  function intensityGraph(rows){const items=[...rows].sort((a,b)=>new Date(a.when)-new Date(b.when)).slice(-20);if(!items.length)return '<div class="empty">Your chart starts with the first committed record.</div>';const x=i=>40+(items.length===1?215:i*430/(items.length-1));const y=n=>180-Number(n)*14;const poly=items.map((e,i)=>`${x(i)},${y(e.intensity)}`).join(' ');return `<svg viewBox="0 0 510 215" role="img" aria-label="Emotion intensity in your recent committed records"><path d="M40 33V180H475" fill="none" stroke="#dae3db" stroke-width="2"/>${[0,5,10].map(n=>`<line x1="40" y1="${y(n)}" x2="475" y2="${y(n)}" stroke="#e4eae2" stroke-dasharray="4 4"/><text x="14" y="${y(n)+4}" fill="#9ca99d" font-size="11">${n}</text>`).join('')}<polyline points="${poly}" fill="none" stroke="#699c84" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"/>${items.map((e,i)=>`<circle cx="${x(i)}" cy="${y(e.intensity)}" r="4" fill="#c98f63"><title>${text(e.title||'Event')}: ${clamp(e.intensity,0,10)}/10</title></circle>`).join('')}<text x="40" y="204" font-size="10" fill="#9ba69d">${dateString(items[0].when)}</text><text x="475" y="204" font-size="10" fill="#9ba69d" text-anchor="end">${dateString(items.at(-1).when)}</text></svg>`}

  function dataView(){const method=STORE.method==='indexeddb'?'IndexedDB':'browser local storage';return `<div class="grid-main"><section class="card"><div class="overline">DATA SOVEREIGNTY</div><h2>Your records live on this device.</h2><p>Rootline has no account system, analytics, cloud database, tracking scripts, third-party fonts, or external JavaScript. Your entries are stored using ${method}. The app files can be hosted on GitHub Pages without sending your journal content to GitHub.</p><div class="soft-panel warm"><strong>Privacy limits:</strong> Device storage is not end-to-end encrypted. Someone with access to your unlocked browser profile may be able to read it. Browser resets, private mode, changing devices, or clearing website data can erase entries. Export regularly and keep backups in a private, protected location.</div><div class="privacy-row"><div><strong>Export a complete JSON backup</strong><p>Includes staged entries, committed files, roots, trust evidence, tags, and your current draft.</p></div><button class="btn dark" data-action="export">Export JSON</button></div><div class="privacy-row"><div><strong>Import or merge a backup</strong><p>Merge by record ID or replace everything on this device. You choose after selecting a file.</p></div><button class="btn light" data-action="import">Import JSON</button></div><div class="privacy-row"><div><strong>Erase all local records</strong><p>Only this app's database on this device. This cannot be undone without a separate backup.</p></div><button class="btn warning" data-action="erase-all">Erase data</button></div></section><div class="flow"><section class="card"><h3>Installable, offline, native</h3><p>Plain HTML + CSS + JavaScript + IndexedDB + service worker + web app manifest. No packages, build pipeline, or CDN.</p><button class="btn light" data-action="install">Install app</button><p class="tiny quiet">If your browser doesn't offer installation, use its “Add to Home Screen” menu. Install requires HTTPS or localhost.</p></section><section class="card"><h3>GitHub Pages ready</h3><p>Upload the extracted project files to a repository. In Settings → Pages, select “Deploy from a branch,” main, /(root). The README has detailed steps. Service workers work on GitHub Pages' HTTPS origin.</p></section><section class="card"><h3>Important boundaries</h3><p>This is a self-reflection record, not a diagnostic tool or therapy protocol. It cannot decide if a parent has changed, prove the origin of a memory, or determine whether someone else's motives were harmful. Those conclusions require real-life evidence, context, and sometimes professional support.</p></section></div></div><div class="spacer"></div><section class="card"><h3>Sources and useful reading</h3><div class="source-links"><a target="_blank" rel="noopener noreferrer" href="https://www.ptsd.va.gov/understand/what/trauma_triggers.asp">U.S. VA — how reminders can activate memories</a><a target="_blank" rel="noopener noreferrer" href="https://www.apa.org/ptsd-guideline/patients-and-families">American Psychological Association — trauma and thought patterns</a><a target="_blank" rel="noopener noreferrer" href="https://developer.mozilla.org/en-US/docs/Web/API/IndexedDB_API">MDN — IndexedDB storage</a><a target="_blank" rel="noopener noreferrer" href="https://docs.github.com/en/pages/getting-started-with-github-pages/configuring-a-publishing-source-for-your-github-pages-site">GitHub — Pages publishing sources</a></div></section>`}

  function upsert(collection,row){const index=collection.findIndex(x=>x.id===row.id);if(index>=0)collection[index]=row;else collection.push(row)}
  function hasDraftContent(d=state.draft){return Boolean(String(d.title||'').trim()||String(d.presentEvent||'').trim()||String(d.firstMeaning||'').trim())}
  function clearDraft(){state.draft=episodeBlank();ui.step=0}
  async function fileEpisode(status){
    const d=structuredClone(state.draft);
    if(!hasDraftContent(d)){toast('Give this entry a title or describe the present event first.');return}
    d.id=d.id||id();d.status=status;d.updatedAt=timeNow();
    d.title=String(d.title||'').trim()||String(d.presentEvent||'').trim().slice(0,80)||'Untitled event';
    d.emotions=arr(d.emotions);d.tagIds=arr(d.tagIds);d.rootIds=arr(d.rootIds);d.intensity=clamp(d.intensity,0,10);
    upsert(state.episodes,d);clearDraft();await persist();navigate('archive');toast(status==='staged'?'Intake staged for later.':'Filed. You can revise this record when new information arrives.');
  }
  function editEpisode(item){if(!item)return;closeModal();if(hasDraftContent()&&state.draft.id!==item.id&&!confirm('You have another unfinished intake. Stage or finish it before replacing the draft. Continue and replace it?'))return;state.draft={...episodeBlank(),...structuredClone(item)};ui.step=0;persist();navigate('stage')}
  async function eraseRecord(type,recordId){const config={episode:['episodes','Delete this emotional record?'],origin:['roots','Delete this origin? Links to it in other records will be removed.'],trust:['trust','Delete this trust observation?']};const [collection,prompt]=config[type]||[];if(!collection||!confirm(`${prompt} This cannot be undone without a backup.`))return;state[collection]=state[collection].filter(x=>x.id!==recordId);if(type==='origin')for(const e of state.episodes)e.rootIds=arr(e.rootIds).filter(x=>x!==recordId);if(type==='episode'&&state.draft.id===recordId)clearDraft();await persist();closeModal();render();toast('Record deleted from this device.')}
  let pendingImport=null;
  function doExport(){
    const backup={format:'rootline-emotional-atlas',exportedAt:timeNow(),...structuredClone(state)};
    const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`rootline-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1200);toast('JSON backup prepared. Keep the file private.');
  }
  function mergeSets(oldRows,newRows){const map=new Map(oldRows.map(x=>[x.id,x]));for(const row of newRows){if(!map.has(row.id))map.set(row.id,row)}return [...map.values()]}
  async function doImport(){if(!pendingImport)return;const choice=document.querySelector('input[name="import-strategy"]:checked')?.value||'merge';if(choice==='replace'&&!confirm('Replace every record currently saved in this browser with the imported backup?'))return;const imported=pendingImport;const next=choice==='replace'?imported:{...state,episodes:mergeSets(state.episodes,imported.episodes),roots:mergeSets(state.roots,imported.roots),trust:mergeSets(state.trust,imported.trust),tags:mergeSets(state.tags,imported.tags)};state=next;await persist();pendingImport=null;closeModal();navigate('home');toast(choice==='merge'?'New records merged by ID. Existing records were kept.':'Backup restored on this device.')}
  function aboutFramework(){showModal(`<div class="overline">ROOTLINE / WORKING PRINCIPLES</div><h2>Two things can be true.</h2><p><strong>1. A feeling may be understandable.</strong> Your body can recognize a pattern because you learned to anticipate danger, conflict, rejection, or blame.</p><p><strong>2. An interpretation may not be certain.</strong> A present-day cue might be genuinely unfair, partly ambiguous, or mostly an old echo. The app cannot know without evidence.</p><p><strong>3. Your response is still yours to shape.</strong> A protective strategy can make sense in childhood and still harm a relationship today. Responsibility does not require self-punishment.</p><p><strong>4. People can change, or fail to.</strong> Track observed behaviour, consistent boundary respect, and meaningful repair. A BPD diagnosis does not settle that question.</p><p><strong>5. No forced memory work.</strong> A root can remain unknown. If journaling raises intense distress or dissociation, stop and work with a trained clinician.</p><button class="btn dark" data-action="modal-close">Continue at my pace</button>`)}
  function openTagArchive(){ui.archiveTag=ui.mapTag;ui.archiveStatus='all';navigate('archive')}

  document.addEventListener('click',async e=>{
    const nav=e.target.closest('[data-nav]');if(nav){navigate(nav.dataset.nav);return}
    const target=e.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;
    switch(action){
      case 'about-framework':aboutFramework();break;
      case 'modal-close':closeModal();break;
      case 'step':ui.step=clamp(target.dataset.step,0,3);render();break;
      case 'step-next':ui.step=Math.min(3,ui.step+1);render();break;
      case 'step-back':ui.step=Math.max(0,ui.step-1);render();break;
      case 'stage-save':await fileEpisode('staged');break;
      case 'commit':await fileEpisode('committed');break;
      case 'new-intake':if(hasDraftContent()&&!confirm('Clear this unfinished intake? Stage it first if you want to keep it.'))return;clearDraft();persist();render();break;
      case 'toggle-draft-tag':{
        const t=target.dataset.tag;const tags=arr(state.draft.tagIds);state.draft.tagIds=tags.includes(t)?tags.filter(x=>x!==t):[...tags,t];queueDraft();render();break;
      }
      case 'view-episode':{const item=state.episodes.find(x=>x.id===target.dataset.id);if(item)showModal(episodeDetails(item));break}
      case 'edit-episode':editEpisode(state.episodes.find(x=>x.id===target.dataset.id));break;
      case 'delete-episode':await eraseRecord('episode',target.dataset.id);break;
      case 'new-origin':showModal(originForm(null));break;
      case 'view-origin':{const item=byRoot(target.dataset.id);if(item)showModal(originDetails(item));break}
      case 'edit-origin':{const item=byRoot(target.dataset.id);if(item)showModal(originForm(item));break}
      case 'delete-origin':await eraseRecord('origin',target.dataset.id);break;
      case 'new-trust':showModal(trustForm(null));break;
      case 'view-trust':{const item=state.trust.find(x=>x.id===target.dataset.id);if(item)showModal(trustDetails(item));break}
      case 'edit-trust':{const item=state.trust.find(x=>x.id===target.dataset.id);if(item)showModal(trustForm(item));break}
      case 'delete-trust':await eraseRecord('trust',target.dataset.id);break;
      case 'filter-tag':ui.mapTag=target.dataset.tag;navigate('atlas');break;
      case 'select-map-tag':ui.mapTag=ui.mapTag===target.dataset.tag?'all':target.dataset.tag;render();break;
      case 'clear-map':ui.mapTag='all';render();break;
      case 'open-tag-archive':openTagArchive();break;
      case 'map-node':{
        const nodeType=target.dataset.type,nodeId=target.dataset.id;
        if(nodeType==='episode'){const item=state.episodes.find(x=>x.id===nodeId);if(item)showModal(episodeDetails(item))}
        if(nodeType==='origin'){const item=byRoot(nodeId);if(item)showModal(originDetails(item))}
        if(nodeType==='tag'){ui.mapTag=nodeId;render()}
        break;
      }
      case 'export':doExport();break;
      case 'import':document.getElementById('import-file').click();break;
      case 'import-confirm':await doImport();break;
      case 'erase-all':{
        if(!confirm('Erase all local Rootline records, origins, trust observations, tags, and the unfinished draft?'))return;
        if(!confirm('Final confirmation: this cannot be undone without an exported backup. Erase everything?'))return;
        state=freshState();await STORE.clear();await persist();navigate('home');toast('All local Rootline entries erased.');break;
      }
      case 'install':if(window.rootlineInstallPrompt){window.rootlineInstallPrompt.prompt();window.rootlineInstallPrompt.userChoice.finally(()=>window.rootlineInstallPrompt=null)}else toast('Use your browser menu: Install app or Add to Home Screen.');break;
    }
  });

  document.addEventListener('input',e=>{
    const f=e.target.closest('#episode-form');if(f){
      const name=e.target.name;if(!EPISODE_FIELDS.includes(name))return;
      if(name==='emotions'||name==='rootIds')state.draft[name]=[...f.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value);
      else if(name==='when')state.draft.when=fromLocal(e.target.value);
      else if(name==='intensity'){state.draft.intensity=clamp(e.target.value,0,10);const output=document.getElementById('intensity-output');if(output)output.textContent=state.draft.intensity;document.getElementById('distress-note')?.classList.toggle('hidden',state.draft.intensity<8)}
      else state.draft[name]=e.target.value;
      state.draft.updatedAt=timeNow();queueDraft();return;
    }
    if(e.target.id==='archive-search'){ui.archiveQuery=e.target.value;document.getElementById('archive-results').innerHTML=archiveFiltered().map(x=>episodeRow(x)).join('')||'<div class="empty">No matching records.</div>';return}
  });
  document.addEventListener('change',e=>{
    if(e.target.closest('#episode-form')&&e.target.name){
      const name=e.target.name;if(!EPISODE_FIELDS.includes(name))return;
      if(name==='emotions'||name==='rootIds')state.draft[name]=[...document.querySelectorAll(`input[name="${name}"]:checked`)].map(x=>x.value);
      else if(name==='when')state.draft.when=fromLocal(e.target.value);
      else if(name==='intensity')state.draft.intensity=clamp(e.target.value,0,10);
      else state.draft[name]=e.target.value;
      queueDraft();return;
    }
    if(['archive-status','archive-person','archive-tag'].includes(e.target.id)){ui[{ 'archive-status':'archiveStatus','archive-person':'archivePerson','archive-tag':'archiveTag'}[e.target.id]]=e.target.value;render();return}
    if(e.target.id==='trust-person'){ui.trustPerson=e.target.value;render()}
  });
  document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('svg-node')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}))}});
  document.addEventListener('submit',async e=>{
    if(e.target.id==='origin-form'){
      e.preventDefault();const fd=new FormData(e.target),existing=state.roots.find(x=>x.id===e.target.dataset.id);
      const row={id:existing?.id||id(),createdAt:existing?.createdAt||timeNow(),updatedAt:timeNow(),title:String(fd.get('title')||'').trim(),period:String(fd.get('period')||'').trim(),person:String(fd.get('person')||'').trim(),description:String(fd.get('description')||'').trim(),lesson:String(fd.get('lesson')||'').trim(),source:String(fd.get('source')||'unsure'),today:String(fd.get('today')||'').trim()};if(!row.title){toast('Give the origin a short name.');return}upsert(state.roots,row);await persist();closeModal();render();toast('Origin saved.');return;
    }
    if(e.target.id==='trust-form'){
      e.preventDefault();const fd=new FormData(e.target),existing=state.trust.find(x=>x.id===e.target.dataset.id);
      const row={id:existing?.id||id(),createdAt:existing?.createdAt||timeNow(),updatedAt:timeNow(),title:String(fd.get('title')||'').trim(),when:String(fd.get('when')||timeNow().slice(0,10)),person:String(fd.get('person')||'').trim(),behavior:String(fd.get('behavior')||'').trim(),boundary:String(fd.get('boundary')||'').trim(),evidence:String(fd.get('evidence')||'unknown'),repair:String(fd.get('repair')||'').trim(),contact:String(fd.get('contact')||'').trim()};if(!row.title||!row.person){toast('Give this observation a title and person.');return}upsert(state.trust,row);await persist();closeModal();render();toast('Trust observation saved.');return;
    }
    if(e.target.id==='tag-form'){
      e.preventDefault();const fd=new FormData(e.target);const name=String(fd.get('name')||'').trim(),desc=String(fd.get('description')||'').trim();if(!name){toast('A label name is required.');return}if(state.tags.some(t=>t.name.toLowerCase()===name.toLowerCase())){toast('That pressure-point label already exists.');return}state.tags.push({id:`CUSTOM-${id()}`,name:name.slice(0,85),description:desc.slice(0,350),createdAt:timeNow()});await persist();render();toast('New classification destination added.');return;
    }
  });
  document.getElementById('close-modal').addEventListener('click',closeModal);
  modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});
  document.getElementById('import-file').addEventListener('change',async e=>{
    const file=e.target.files?.[0];if(!file)return;
    try{
      if(file.size>30_000_000)throw new Error('The selected backup is larger than 30 MB.');
      const parsed=JSON.parse(await file.text());if(parsed.format!=='rootline-emotional-atlas')throw new Error('This is not a Rootline JSON export.');
      const imported=normalize(parsed);pendingImport=imported;
      showModal(`<div class="overline">IMPORT / REVIEW FIRST</div><h2>Backup recognized</h2><p>This backup contains ${imported.episodes.length} episodes, ${imported.roots.length} origins, ${imported.trust.length} trust observations, and ${imported.tags.length} classification labels.</p><div class="field"><span class="field-label">Choose how to import</span><label class="origin-option"><input type="radio" name="import-strategy" value="merge" checked><span><strong>Merge (recommended)</strong><small>Add IDs not already present. Keep all existing records and your current draft.</small></span></label><label class="origin-option"><input type="radio" name="import-strategy" value="replace"><span><strong>Replace</strong><small>Overwrite everything saved on this device with the backup, including the draft.</small></span></label></div><div class="soft-panel warm">A JSON backup is readable text. Keep it private. Import files only from sources you trust.</div><div class="spacer"></div><button class="btn dark" data-action="import-confirm">Continue with import</button>`);
    }catch(error){toast(`Import failed: ${error.message}`)}finally{e.target.value=''}
  });
  window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();window.rootlineInstallPrompt=e});
  window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(pageTitle[next]&&next!==ui.page){ui.page=next;render()}});
  if('serviceWorker'in navigator&&(location.protocol==='https:'||location.hostname==='localhost'||location.hostname==='127.0.0.1'))window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));

  (async()=>{
    const method=await STORE.init();
    if(method==='unavailable'){document.getElementById('storage-note').textContent='Storage unavailable';document.getElementById('save-state').textContent='⚠ Entries may not persist';}
    else{document.getElementById('storage-note').textContent=`Private ${method==='indexeddb'?'device database':'browser storage'}`;try{const existing=await STORE.get();if(existing)state=normalize(existing)}catch(error){document.getElementById('save-state').textContent='⚠ Saved data needs review';toast(`Could not load saved records: ${error.message}`)}}
    const route=location.hash.slice(1);if(pageTitle[route])ui.page=route;
    render();if(method!=='unavailable')document.getElementById('save-state').textContent='✓ Local-only workspace';
  })();
})();
